content:
{
 "command": "make test-fast 2>&1 | tail -40",
 "description": "Run fast test suite"
}

{
 "pattern": "LEDGERLINE_FX_FIXTURES",
 "output_mode": "content"
}

{
 "mode": "filter",
 "query": "LEDGERLINE_FX_FIXTURES fixtures fx rates"
}

{
 "command": "LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast 2>&1 | tail -30",
 "description": "Rerun fast tests with FX fixtures env var"
}

{
 "command": "cat docs/testing.md; ls -R tests | head -40; git log --oneline -- tests/fixtures | head",
 "description": "Inspect testing docs and fixtures"
}

{
 "command": "python scripts/gen_fx_fixtures.py && git status --short && LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast 2>&1 | tail -15",
 "description": "Generate FX fixtures and rerun tests"
}

{
 "mode": "filter",
 "query": "PSP sandbox region"
}
